"use strict";const fs=require("fs"),path=require("path"),zlib=require("zlib"),config=require("../config/config"),BACKUP_DIR=path.resolve(__dirname,"..","..","backups"),MAX_BACKUP_AGE_DAYS=30;function ensureBackupDir(){fs.existsSync(BACKUP_DIR)||fs.mkdirSync(BACKUP_DIR,{recursive:!0})}function createBackup(r=null){try{ensureBackupDir();const e=config.sqlitePath;if(!fs.existsSync(e))return{success:!1,error:"Database file not found: "+e};if(r&&typeof r.exec=="function")try{r.exec("PRAGMA wal_checkpoint(TRUNCATE);")}catch{}const t=new Date,c=u=>String(u).padStart(2,"0"),s=`clinic_hse_backup_${`${t.getFullYear()}-${c(t.getMonth()+1)}-${c(t.getDate())}_${c(t.getHours())}${c(t.getMinutes())}${c(t.getSeconds())}`}.db.gz`,n=path.join(BACKUP_DIR,s),o=fs.readFileSync(e),a=zlib.gzipSync(o);fs.writeFileSync(n,a);const l=(o.length/(1024*1024)).toFixed(2),p=(a.length/(1024*1024)).toFixed(2);return rotateBackups(),{success:!0,fileName:s,path:n,timestamp:t.toISOString(),originalSizeMB:l,compressedSizeMB:p}}catch(e){return{success:!1,error:e.message}}}function rotateBackups(){try{ensureBackupDir();const r=fs.readdirSync(BACKUP_DIR),e=Date.now(),t=MAX_BACKUP_AGE_DAYS*24*60*60*1e3;r.forEach(c=>{if(c.startsWith("clinic_hse_backup_")&&c.endsWith(".db.gz")){const i=path.join(BACKUP_DIR,c),s=fs.statSync(i);e-s.mtimeMs>t&&fs.unlinkSync(i)}})}catch{}}function listBackups(){try{return ensureBackupDir(),fs.readdirSync(BACKUP_DIR).filter(e=>e.startsWith("clinic_hse_backup_")&&e.endsWith(".db.gz")).map(e=>{const t=path.join(BACKUP_DIR,e),c=fs.statSync(t);return{fileName:e,sizeMB:(c.size/(1024*1024)).toFixed(2),createdAt:c.birthtime.toISOString()}}).sort((e,t)=>t.createdAt.localeCompare(e.createdAt))}catch{return[]}}function startDailyBackupScheduler(r){setTimeout(()=>{createBackup(r)},1e4),setInterval(()=>{createBackup(r)},864e5)}module.exports={createBackup,listBackups,rotateBackups,startDailyBackupScheduler};
